static void BNCaptureScroll(BNView *view,NSString *path,NSMutableDictionary *saved) {
#if TARGET_OS_OSX
    if([view isKindOfClass:[NSScrollView class]]) {NSPoint point=((NSScrollView *)view).contentView.bounds.origin;saved[path]=@[@(point.x),@(point.y)];}
#else
    if([view isKindOfClass:[UIScrollView class]]) {CGPoint point=((UIScrollView *)view).contentOffset;saved[path]=@[@(point.x),@(point.y)];}
#endif
    NSUInteger index=0;for(BNView *child in view.subviews)BNCaptureScroll(child,[path stringByAppendingFormat:@"/%lu",(unsigned long)index++],saved);
}
static void BNRestoreScroll(BNView *view,NSString *path,NSDictionary *saved) {
    NSArray *point=saved[path];if(point.count==2) {
#if TARGET_OS_OSX
        if([view isKindOfClass:[NSScrollView class]]){NSScrollView *scroll=(NSScrollView *)view;[scroll.contentView scrollToPoint:NSMakePoint([point[0] doubleValue],[point[1] doubleValue])];[scroll reflectScrolledClipView:scroll.contentView];}
