        if([view isKindOfClass:[UIScrollView class]])((UIScrollView *)view).contentOffset=CGPointMake([point[0] doubleValue],[point[1] doubleValue]);
#endif
    }
    NSUInteger index=0;for(BNView *child in view.subviews)BNRestoreScroll(child,[path stringByAppendingFormat:@"/%lu",(unsigned long)index++],saved);
}
